package ir.hosein.goldin.data.remote

import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get
import io.ktor.http.isSuccess
import ir.hosein.goldin.data.core.NetworkResult
import ir.hosein.goldin.data.model.DaricResponse
import ir.hosein.goldin.data.model.DigiKalaResponse
import ir.hosein.goldin.data.model.GoldikaResponse
import ir.hosein.goldin.data.model.MiliGoldResponse
import ir.hosein.goldin.data.model.PlatformInfo
import ir.hosein.goldin.data.model.TalainResponse
import ir.hosein.goldin.data.model.TalappGoldResponse
import ir.hosein.goldin.data.model.TalaseaGoldResponse
import ir.hosein.goldin.data.model.WallGoldResponse

class ApiServiceImp(
    private val httpClient: HttpClient
) : ApiService {


    override suspend fun getMiliGoldPrice(): NetworkResult<MiliGoldResponse> {
        return httpClient.safeRequest(PlatformInfo.MILI_GOLD.url)
    }

    override suspend fun getDigikalaGoldPrice(): NetworkResult<DigiKalaResponse> {
        return httpClient.safeRequest(PlatformInfo.DIGI_KALA.url)
    }

    override suspend fun getTalappGoldResponse(): NetworkResult<TalappGoldResponse> {
        return httpClient.safeRequest(PlatformInfo.TALAPP.url)
    }

    override suspend fun getTalaseaGoldPrice(): NetworkResult<TalaseaGoldResponse> {
        return httpClient.safeRequest(PlatformInfo.TALASEA.url)
    }

    override suspend fun getGoldikaResponse(): NetworkResult<GoldikaResponse> {
        return httpClient.safeRequest(PlatformInfo.GOLDIKA.url)
    }

    //new
    override suspend fun getDaricGoldResponse(): NetworkResult<DaricResponse> {
        return httpClient.safeRequest(PlatformInfo.DARK.url)
    }

    override suspend fun getWallGoldResponse(): NetworkResult<WallGoldResponse> {
        return httpClient.safeRequest(PlatformInfo.WALL_GOLD.url)
    }

    override suspend fun getTalainResponse(): NetworkResult<TalainResponse> {
        return httpClient.safeRequest(PlatformInfo.TALAIN.url)
    }


}