package ir.hosein.goldin.repository

import ir.hosein.goldin.data.core.NetworkResult
import ir.hosein.goldin.data.model.PlatformInfo
import ir.hosein.goldin.data.model.PlatformPrice
import ir.hosein.goldin.data.remote.ApiService

class MainRepository(
    private val apiService: ApiService
) {

    suspend fun getPlatformPrice(info: PlatformInfo) : NetworkResult<PlatformPrice>{
        return when(info){
            PlatformInfo.DIGI_KALA -> {
                apiService.getDigikalaGoldPrice().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.gold18.price * 100,
                        lastTimeRefresh = lng
                    )
                }
            }
            PlatformInfo.MILI_GOLD ->{
                apiService.getMiliGoldPrice().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.data.price18 * 100,
                        lastTimeRefresh = lng
                    )
                }
            }
            PlatformInfo.TALASEA -> {
                apiService.getTalaseaGoldPrice().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.price *1000,
                        lastTimeRefresh = lng
                    )
                }
            }
            PlatformInfo.TALAPP -> {
                apiService.getTalappGoldResponse().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.buy_gold,
                        lastTimeRefresh = lng
                    )
                }
            }
            PlatformInfo.GOLDIKA -> {
                apiService.getGoldikaResponse().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.data.price.buy /10,
                        lastTimeRefresh = lng
                    )
                }
            }

            PlatformInfo.TALAIN -> {
                apiService.getTalainResponse().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.prices[0][0].price.buy /10,
                        lastTimeRefresh = lng
                    )
                }
            }
            PlatformInfo.WALL_GOLD ->{
                apiService.getWallGoldResponse().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.result.price.toLong(),
                        lastTimeRefresh = lng
                    )
                }
            }
            PlatformInfo.DARK -> {
                apiService.getDaricGoldResponse().mapWithTime { response, lng ->
                    PlatformPrice(
                        platformInfo = info,
                        goldPrice = response.Data.BestBuyPrice.toLong(),
                        lastTimeRefresh = lng
                    )
                }
            }
        }
    }


}