package ir.hosein.goldin.ui.theme

import androidx.compose.runtime.Composable
import androidx.compose.runtime.compositionLocalOf
import androidx.compose.ui.platform.LocalWindowInfo
import androidx.compose.ui.unit.dp

enum class WindowSize {
    Compact,
    Medium,
    Expanded
}

val LocalWindowSize = compositionLocalOf<WindowSize> { WindowSize.Compact }


@Composable
fun calculateWindowSizeInfo(): WindowSize {
    val windowInfo = LocalWindowInfo.current
    val width = windowInfo.containerDpSize.width
    val height = windowInfo.containerDpSize.height
    return when {
        width > 1200.dp && height >= 600.dp -> WindowSize.Expanded
        width > 750.dp && height >= 480.dp -> WindowSize.Medium
        else -> WindowSize.Compact
    }
}