package ir.hosein.goldin.repository

import com.russhwolf.settings.ExperimentalSettingsApi
import com.russhwolf.settings.ObservableSettings
import com.russhwolf.settings.coroutines.getBooleanOrNullFlow
import com.russhwolf.settings.coroutines.getBooleanOrNullStateFlow
import com.russhwolf.settings.coroutines.getBooleanStateFlow
import com.russhwolf.settings.set
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.SharingStarted

class SettingRepository(
    private val settings: ObservableSettings
) {

    private object Keys {
        const val APPLICATION_THEME = "APPLICATION_THEME"
    }

    @OptIn(ExperimentalSettingsApi::class)
    fun getThemeDark(): Flow<Boolean?> {
        return settings.getBooleanOrNullStateFlow(
            key = Keys.APPLICATION_THEME,
            coroutineScope = CoroutineScope(SupervisorJob() + Dispatchers.Default),
            sharingStarted = SharingStarted.Eagerly
        )
    }

      fun setThemeDark(value: Boolean?) {
        settings[Keys.APPLICATION_THEME] = value
    }
}