package ir.hosein.goldin.navigation

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.ui.Modifier
import androidx.navigation3.runtime.NavBackStack
import androidx.navigation3.runtime.NavKey
import androidx.navigation3.runtime.entryProvider
import androidx.navigation3.ui.NavDisplay
import ir.hosein.goldin.ui.screen.arz.ArzScreen
import ir.hosein.goldin.ui.screen.crypto.CryptoScreen
import ir.hosein.goldin.ui.screen.home.HomeScreen
import ir.hosein.goldin.ui.screen.setting.SettingScreen
import ir.hosein.goldin.viewModel.SettingViewModel
import kotlinx.coroutines.delay
import kotlin.time.Duration.Companion.milliseconds

@Composable
fun GoldinNavDisplay(
    backStack: NavBackStack<NavKey>,
    darkThem: Boolean?,
    onChangeThem: (value: Boolean?) -> Unit
) {

    NavDisplay(
        modifier = Modifier.fillMaxSize(),
        backStack = backStack,
        entryProvider = entryProvider {
            entry<Routes.HomeScreen> { HomeScreen() }
            entry<Routes.ArzScreen> { ArzScreen() }
            entry<Routes.CryptoScreen> { CryptoScreen() }
            entry<Routes.SettingScreen> {
                val args = it.darkTheme
                LaunchedEffect(args){
                    if (args!=null){ onChangeThem(args) }
                }
                SettingScreen(darkThem, onChangeThem)
            }
        }
    )
}