package ir.hosein.goldin.viewModel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import ir.hosein.goldin.data.core.NetworkResult
import ir.hosein.goldin.data.model.CryptoItem
import ir.hosein.goldin.repository.CryptoRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.onStart
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class CryptoViewModel(
    private val repository: CryptoRepository
) : ViewModel() {

    private val _allCryptoList =
        MutableStateFlow<NetworkResult<List<CryptoItem>>>(NetworkResult.Idle)

    val allCryptoList = _allCryptoList.onStart { getCrypto() }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.Lazily,
            initialValue = NetworkResult.Idle
        )

    fun onIntent(intent: CryptoIntent) {
        when (intent) {
            CryptoIntent.RefreshAllPlatform -> getCrypto()
        }
    }

    private fun getCrypto() {
        viewModelScope.launch {
            _allCryptoList.emit(NetworkResult.Loading)
            val response = repository.getAllCryptoList()
            _allCryptoList.emit(response)
        }

    }

}