@Composable
internal fun NavScaffold(
    content: @Composable (backStack: NavBackStack<NavKey>) -> Unit
) {

    val windowSize = LocalWindowSize.current
    val showLargeNavigation = windowSize != WindowSize.Compact
    val showCompactNavigation = windowSize == WindowSize.Compact

    val destinations = remember { NavigationItem.mainNavigation }
    val config = SavedStateConfiguration {
        serializersModule = SerializersModule {
            polymorphic(NavKey::class) {
                subclass(
                    subclass = Routes.HomeScreen::class,
                    serializer = Routes.HomeScreen.serializer()
                )
                subclass(
                    subclass = Routes.ArzScreen::class,
                    serializer = Routes.ArzScreen.serializer()
                )
                subclass(
                    subclass = Routes.CryptoScreen::class,
                    serializer = Routes.CryptoScreen.serializer()
                )
                subclass(
                    subclass = Routes.SettingScreen::class,
                    serializer = Routes.SettingScreen.serializer()
                )
            }
        }
    }
    val backStack = rememberNavBackStack(config, Routes.HomeScreen)
    WebIntegration(backStack)
    val selectedRoute = backStack.lastOrNull()
    Row(
        modifier = Modifier.fillMaxSize()
            .background(GoldinThem.colors.mainBackground)
    ) {
        AnimatedVisibility(
            visible = showLargeNavigation,
            enter = expandHorizontally(),
            exit = shrinkHorizontally()
        ) {
            //LargeNavigation
            Row(
                Modifier
                    .padding(8.dp)
                    .background(
                        color = GoldinThem.colors.itemColor,
                        shape = RoundedCornerShape(16.dp)
                    )
                    .border(0.5.dp, Color.LightGray.copy(0.2f), RoundedCornerShape(16.dp))
                    .fillMaxHeight()
            ) {
                MainNavigationRail(
                    destinations = destinations,
                    selectedRoute = selectedRoute.toString(),
                    expanded = windowSize == WindowSize.Expanded,
                    onClick = { newRoute ->
                        backStack.removeLastOrNull()
                        backStack.add(newRoute)
                    }
                )
            }
        }
        Column(
            modifier = Modifier.fillMaxSize()
                .weight(1f)
        ) {
            Box(
                modifier = Modifier.fillMaxSize()
                    .weight(1f).clipToBounds()
            ) {
                content.invoke(backStack)
            }

            AnimatedVisibility(
                visible = showCompactNavigation,
                enter = expandHorizontally(),
                exit = shrinkHorizontally()
            ) {
                //CompactNavigation
                Column(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    HorizontalDivider(thickness = 0.7.dp, color = Color.LightGray.copy(0.4f))
                    BottomNavigation(
                        destinations = destinations,
                        selectedRoute = selectedRoute.toString(),
                        onClick = { newRoute ->
                            if (selectedRoute.toString() != Routes.HomeScreen.toString()) {
                                backStack.removeLastOrNull()
                            }
                            backStack.add(newRoute)
                        }
                    )
                }

            }
        }
    }
}

@Composable
fun MainNavigationRail(
    destinations: List<NavigationItem>,
    selectedRoute: String,
    expanded: Boolean,
    onClick: (Routes) -> Unit
) {
    val width by animateDpAsState(
        targetValue = if (expanded) 230.dp else 150.dp,
        label = "width MainNavigationRail",
        animationSpec = spring(
            visibilityThreshold = Dp.VisibilityThreshold,
            stiffness = Spring.StiffnessLow
        )
    )
    Column(
        modifier = Modifier.width(width)
            .padding(12.dp)
            .animateContentSize(),
        verticalArrangement = Arrangement.spacedBy(5.dp)
    ) {
        Spacer(Modifier.height(2.dp))
        destinations.forEach { destination ->
            NavRailMenuItem(
                selectedIcon = destination.selectedIcon,
                unSelectedIcon = destination.unSelectedIcon,
                title = destination.title,
                selected = selectedRoute == destination.route.toString(),
                expanded = expanded,
                onClick = { onClick(destination.route) }
            )
        }

    }
}

@Composable
fun NavRailMenuItem(
    selectedIcon: DrawableResource,
    unSelectedIcon: DrawableResource,
    title: String,
    selected: Boolean,
    expanded: Boolean,
    onClick: () -> Unit,
) {

    val containerColor by animateColorAsState(
        targetValue = if (selected) GoldinThem.colors.goldColor.copy(0.15f)
        else Color.Transparent,
        label = "containerColor"
    )
    val contentColor by animateColorAsState(
        targetValue = if (selected) GoldinThem.colors.goldColor
        else GoldinThem.colors.textColor,
        label = "contentColor"
    )
    val itemPadding by animateDpAsState(
        targetValue = if (expanded) 11.dp
        else 8.dp,
        label = "itemPadding"
    )
    val itemModifier = Modifier
        .pointerHoverIcon(PointerIcon.Hand)
        .clip(RoundedCornerShape(12.dp))
        .fillMaxWidth()
        .selectable(
            selected = selected,
            role = Role.Tab,
            enabled = true,
            onClick = onClick
        )
        .background(containerColor)
        .padding(itemPadding)
    SharedTransitionLayout(
        modifier = itemModifier
    ) {
        AnimatedContent(
            targetState = expanded
        ) { isExpanded ->
            val itemContent = @Composable {
                Icon(
                    painter = painterResource(if (selected) selectedIcon else unSelectedIcon),
                    contentDescription = null,
                    modifier = Modifier.size(25.dp)
                        .sharedElement(
                            rememberSharedContentState(key = "icon:$title"),
                            animatedVisibilityScope = this@AnimatedContent
                        ),
                    tint = contentColor
                )

                Text(
                    text = title,
                    style = GoldinThem.typoGraphy.bodyLarge,
                    fontWeight = FontWeight.SemiBold,
                    color = contentColor,
                    modifier = Modifier.sharedElement(
                        rememberSharedContentState(key = "title:$title"),
                        animatedVisibilityScope = this@AnimatedContent
                    )
                )
            }
            if (isExpanded) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    itemContent.invoke()
                }
            } else {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(
                        6.dp,
                        alignment = Alignment.CenterVertically
                    )
                ) {
                    itemContent.invoke()
                }
            }
        }
    }

}


@Composable
fun BottomNavigation(
    destinations: List<NavigationItem>,
    selectedRoute: String,
    onClick: (Routes) -> Unit
) {
    Row(
        modifier = Modifier
            .navigationBarsPadding()
            .fillMaxWidth()
            .padding(horizontal = 4.dp, vertical = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(7.dp, Alignment.CenterHorizontally)
    ) {
        destinations.forEach { destination ->
            BottomNavigationItem(
                selectedIcon = destination.selectedIcon,
                unSelectedIcon = destination.unSelectedIcon,
                selected = selectedRoute == destination.route.toString(),
                onClick = { onClick(destination.route) },
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f, fill = false)
            )

        }
    }
}

@Composable
fun BottomNavigationItem(
    modifier: Modifier,
    selectedIcon: DrawableResource,
    unSelectedIcon: DrawableResource,
    selected: Boolean,
    onClick: () -> Unit,
) {
    val contentColor by animateColorAsState(
        targetValue = if (selected) GoldinThem.colors.goldColor
        else GoldinThem.colors.textColor,
        label = "contentColor"
    )
    Icon(
        painter = painterResource(if (selected) selectedIcon else unSelectedIcon),
        contentDescription = null,
        modifier = modifier
            .pointerHoverIcon(PointerIcon.Hand)
            .clip(RoundedCornerShape(12.dp))
            .selectable(
                selected = selected,
                role = Role.Tab,
                onClick = onClick
            )
            .padding(10.dp)
            .size(27.dp),
        tint = contentColor
    )
}