@Composable
fun ArzScreen(arzViewModel: ArzViewModel = koinViewModel()) {
    val arzState by arzViewModel.arzState.collectAsState()
    val windowSize = LocalWindowSize.current
    val gridCells = remember(key1 = windowSize) {
        when (windowSize) {
            WindowSize.Compact -> 1
            WindowSize.Medium -> 2
            WindowSize.Expanded -> 3
        }
    }

    Scaffold(
        containerColor = GoldinThem.colors.mainBackground,
        topBar = { MainTopBar("رصد ارز های خارجی") }
    ) { innerPadding ->
        HandleUiState(
            state = arzState,
            onRefreshAction = {arzViewModel.onIntent(ArzIntent.RefreshAllPlatform)},
        ) { response ->
            LazyVerticalGrid(
                columns = GridCells.Fixed(gridCells),
                modifier = Modifier.fillMaxSize(),
                contentPadding = innerPadding
            ) {
                item(span = { GridItemSpan(maxLineSpan) }, key = "header") {
                    RefreshHeader(
                        title = "آخرین قیمت ها",
                        onRefreshAll ={ arzViewModel.onIntent(ArzIntent.RefreshAllPlatform) }
                    )
                }
                items(response.data, key = {it.representation_name}) { res ->
                    ArzItemCard(
                        modifier = Modifier.animateItem(),
                        title = res.representation_name,
                        price = res.price_in_irt,
                        symbol = res.symbol
                    )
                }
            }
        }

    }
}

@Composable
private fun ArzItemCard(
    modifier: Modifier,
    title: String,
    symbol: String,
    price: String,
) {
    Row(
        modifier = modifier
            .padding(8.dp)
            .clip(RoundedCornerShape(12.dp))
            .background(GoldinThem.colors.itemColor)
            .normalBoarder()
            .padding(12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Box(
                modifier = Modifier
                    .background(
                     color =    GoldinThem.colors.textColor.copy(.10f),
                        shape = RoundedCornerShape(8.dp)
                    ),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = symbol,
                    style = GoldinThem.typoGraphy.bodyMedium,
                    color = GoldinThem.colors.textColor,
                    modifier = Modifier.padding(4.dp)
                )
            }
            Text(
                text = title,
                style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 19.sp),
                color = GoldinThem.colors.textColor
            )
        }


        Text(
            text = buildAnnotatedString {
                append(price.byLocateAndSeparator())
                withStyle(style = GoldinThem.typoGraphy.titleMedium.toSpanStyle()) {
                    append(" تومان")
                }
            },
            style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 20.sp),
            color = GoldinThem.colors.textColor
        )

    }
}