package ir.hosein.goldin.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.navigation3.runtime.NavBackStack
import androidx.navigation3.runtime.NavKey
import com.github.terrakok.navigation3.browser.ChronologicalBrowserNavigation
import com.github.terrakok.navigation3.browser.HierarchicalBrowserNavigation
import com.github.terrakok.navigation3.browser.buildBrowserHistoryFragment
import com.github.terrakok.navigation3.browser.getBrowserHistoryFragmentName
import com.github.terrakok.navigation3.browser.getBrowserHistoryFragmentParameters
import kotlin.js.ExperimentalWasmJsInterop
import kotlin.js.js


@OptIn(ExperimentalWasmJsInterop::class)
private fun isMobileBrowser(): Boolean = js(
    """{
          if (navigator.userAgentData && navigator.userAgentData.mobile) {
            return navigator.userAgentData.mobile;
          }
          if (window.matchMedia && window.matchMedia('(pointer: coarse)').matches) {
            return window.innerWidth <= 820;
          }
          return /Mobi|Android|iPhone|iPad|iPod|IEMobile|Opera Mini|CriOS/i.test(navigator.userAgent);
      }"""
)


fun NavKey.toBrowserHistoryFragment(): String = when (this) {
    is Routes.HomeScreen -> buildBrowserHistoryFragment("home")
    is Routes.ArzScreen -> buildBrowserHistoryFragment("currency")
    is Routes.CryptoScreen -> buildBrowserHistoryFragment("crypto")
    is Routes.SettingScreen -> {
        val params = buildMap<String, String> {
            darkTheme?.let { put("darkTheme", it.toString()) }
        }
        buildBrowserHistoryFragment(
            name = "setting",
            parameters = params
        )
    }

    else -> buildBrowserHistoryFragment("home")
}

@Composable
fun WebRouting(backStack: NavBackStack<NavKey>) {
    val isMobile = remember { isMobileBrowser() }
    if (false) {
        HierarchicalBrowserNavigation {
            backStack.lastOrNull()?.toBrowserHistoryFragment()
        }
    } else {
        ChronologicalBrowserNavigation(
            backStack = backStack,
            saveKey = { key -> key.toBrowserHistoryFragment() },
            restoreKey = { fragment ->
                val name = getBrowserHistoryFragmentName(fragment)
                val params = getBrowserHistoryFragmentParameters(fragment)
                when (name) {
                    "home" -> Routes.HomeScreen
                    "currency" -> Routes.ArzScreen
                    "crypto" -> Routes.CryptoScreen
                    "setting" -> {
                        val args = params["darkTheme"]?.toBoolean()
                        Routes.SettingScreen(darkTheme = args)
                    }

                    else -> Routes.HomeScreen
                }
            }
        )
    }
}