package ir.hosein.goldin.ui.components

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.statusBarsPadding
import androidx.compose.material3.Text
import androidx.compose.material3.TopAppBar
import androidx.compose.material3.TopAppBarDefaults
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import ir.hosein.goldin.ui.theme.GoldinThem

@Composable
fun MainTopBar(
    title: String
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(GoldinThem.colors.mainBackground),
        contentAlignment = Alignment.TopEnd
    ){
        Text(
            text = title,
            style = GoldinThem.typoGraphy.titleLarge.copy(fontSize = 19.sp),
            fontWeight = FontWeight.SemiBold,
            color = GoldinThem.colors.goldColor,
            modifier = Modifier
                .statusBarsPadding()
                .fillMaxWidth()
                .padding(12.dp)
        )
    }

}