package ir.hosein.goldin.di

import io.ktor.client.HttpClient
import io.ktor.client.plugins.HttpTimeout
import io.ktor.client.plugins.contentnegotiation.ContentNegotiation
import io.ktor.client.plugins.logging.LogLevel
import io.ktor.client.plugins.logging.Logging
import io.ktor.serialization.kotlinx.json.json
import ir.hosein.goldin.data.remote.ApiService
import ir.hosein.goldin.data.remote.ApiServiceImp
import ir.hosein.goldin.repository.ArzRepository
import ir.hosein.goldin.repository.CryptoRepository
import ir.hosein.goldin.repository.MainRepository
import ir.hosein.goldin.repository.SettingRepository
import ir.hosein.goldin.viewModel.ArzViewModel
import ir.hosein.goldin.viewModel.CryptoViewModel
import ir.hosein.goldin.viewModel.MainViewModel
import ir.hosein.goldin.viewModel.SettingViewModel
import kotlinx.serialization.json.Json
import org.koin.core.module.dsl.singleOf
import org.koin.core.module.dsl.viewModelOf
import org.koin.dsl.module

val sharedModule = module {
    single {
        HttpClient(
            engine = get()
        ) {
            install(ContentNegotiation) {
                json(Json {
                    ignoreUnknownKeys = true
                    prettyPrint = true
                    isLenient = true
                })
            }
            install(Logging) { level = LogLevel.BODY }
            install(HttpTimeout) {
                requestTimeoutMillis = 15000 // کل زمان درخواست
                connectTimeoutMillis = 10000 // زمان اتصال به سرور
                socketTimeoutMillis = 15000  // زمان انتظار برای دریافت داده
            }
        }
    }
    //repository
    singleOf(::MainRepository)
    singleOf(::ArzRepository)
    singleOf(::CryptoRepository)
    singleOf(::SettingRepository)
    //viewModel
    viewModelOf(::MainViewModel)
    viewModelOf(::ArzViewModel)
    viewModelOf(::CryptoViewModel)
    viewModelOf(::SettingViewModel)

    single<ApiService> {
        ApiServiceImp(get())
    }

}
