package ir.hosein.goldin.di

import com.russhwolf.settings.ExperimentalSettingsApi
import com.russhwolf.settings.ObservableSettings
import com.russhwolf.settings.StorageSettings
import com.russhwolf.settings.observable.makeObservable
import kotlinx.browser.window
import org.koin.core.module.Module
import org.koin.dsl.module

actual val storageModule: Module = module {
    single<ObservableSettings> { provideSettings() }
}


@OptIn(ExperimentalSettingsApi::class)
fun provideSettings(): ObservableSettings {
    return StorageSettings(window.localStorage).makeObservable()
}