@Composable
fun HomeScreen(mainViewModel: MainViewModel = koinViewModel()) {
    val homeState by mainViewModel.homeUiState.collectAsState()
    val windowSize = LocalWindowSize.current
    val gridCells = remember(key1 = windowSize) {
        when (windowSize) {
            WindowSize.Compact -> 1
            WindowSize.Medium -> 2
            WindowSize.Expanded -> 3
        }
    }

    Scaffold(
        containerColor = GoldinThem.colors.mainBackground,
        topBar = {
            MainTopBar("رصد طلای دیجیتال")
        }
    ) { innerPadding ->
        LazyVerticalGrid(
            columns = GridCells.Fixed(gridCells),
            modifier = Modifier.fillMaxSize(),
            contentPadding = innerPadding
        ) {
            item(
                span = { GridItemSpan(maxLineSpan) },
                key = "BestGoldSection"
            ) {
                if (homeState.bestPrice != null) {
                    BestGoldSection(
                        compact = windowSize == WindowSize.Compact,
                        platformPrice = homeState.bestPrice!!,
                        platformInfo = homeState.bestPrice!!.platformInfo
                    )
                }
            }
            item(span = { GridItemSpan(maxLineSpan) }, key = "RefreshHeader") {
                RefreshHeader(
                    title = "مقایسه پلتفرم ها",
                    onRefreshAll = { mainViewModel.onIntent(HomeIntent.RefreshAllPlatform) }
                )
            }
            items(
                items = homeState.platformsMap.toList().sortedBy { (_, result) ->
                    if (result is NetworkResult.Success) result.data.goldPrice else Long.MAX_VALUE
                },
                key = { it.first.title }
            ) { (info, result) ->
                MobileGoldItem(
                    modifier = Modifier.animateItem(),
                    platformPrice = result, info = info,
                    onRefresh = { mainViewModel.onIntent(HomeIntent.RefreshPlatform(info)) }
                )
            }
        }
    }

}


@Composable
fun BestGoldSection(
    compact: Boolean,
    platformInfo: PlatformInfo,
    platformPrice: PlatformPrice
) {
    val infiniteTransition = rememberInfiniteTransition()
    val shimmerOffset by infiniteTransition.animateFloat(
        initialValue = -1000f,
        targetValue = 1000f,
        animationSpec = infiniteRepeatable(
            animation = tween(3000, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        )
    )

    SharedTransitionLayout(
        modifier = Modifier.fillMaxWidth()
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(12.dp)
                .shadow(elevation = 10.dp, shape = RoundedCornerShape(16.dp))
                .background(
                    brush = Brush.linearGradient(
                        colors = listOf(
                            GoldinThem.colors.bestPriceStartColor,
                            GoldinThem.colors.bestPriceEndColor,
                            GoldinThem.colors.bestPriceStartColor
                        ),
                        start = androidx.compose.ui.geometry.Offset(0f, 0f),
                        end = androidx.compose.ui.geometry.Offset(1000f, 1000f)
                    ),
                    shape = RoundedCornerShape(16.dp)
                )
                .background(
                    brush = Brush.linearGradient(
                        colors = listOf(
                            Color.White.copy(alpha = 0f),
                            Color.White.copy(alpha = 0.2f),
                            Color.White.copy(alpha = 0.4f),
                            Color.White.copy(alpha = 0.2f),
                            Color.White.copy(alpha = 0f),
                        ),
                        start = androidx.compose.ui.geometry.Offset(shimmerOffset, shimmerOffset),
                        end = androidx.compose.ui.geometry.Offset(
                            shimmerOffset + 500f,
                            shimmerOffset + 500f
                        )
                    ),
                    shape = RoundedCornerShape(16.dp)
                )
                .padding(16.dp),
            contentAlignment = Alignment.Center
        ) {
            AnimatedContent(
                targetState = compact,
                label = "layout_animate"
            ) { compactLayout ->
                val sharedModifier = @Composable { key: String ->
                    Modifier.sharedBounds(
                        sharedContentState = rememberSharedContentState(key = key),
                        animatedVisibilityScope = this@AnimatedContent,
                        resizeMode = SharedTransitionScope.ResizeMode.scaleToBounds()
                    )
                }
                if (compactLayout) {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        SectionTitle(modifier = sharedModifier("title"))
                        PlatformBadge(
                            platformInfo = platformInfo,
                            modifier = sharedModifier("badge")
                        )
                        PriceComponent(
                            platformPrice = platformPrice,
                            modifier = sharedModifier("price")
                        )
                    }
                } else {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            SectionTitle(modifier = sharedModifier("title"))
                            PlatformBadge(
                                platformInfo = platformInfo,
                                modifier = sharedModifier("badge")
                            )
                        }
                        PriceComponent(
                            platformPrice = platformPrice,
                            modifier = sharedModifier("price")
                        )

                    }
                }

            }
        }
    }
}

@Composable
private fun SectionTitle(modifier: Modifier = Modifier) {
    Text(
        modifier = modifier,
        text = "بهترین قیمت امروز",
        style = GoldinThem.typoGraphy.titleLarge,
        color = Color.Black,
        fontWeight = FontWeight.Bold
    )
}

@Composable
private fun PlatformBadge(
    platformInfo: PlatformInfo,
    modifier: Modifier = Modifier
) {
    Row(
        modifier = modifier.padding(vertical = 8.dp)
            .background(
                Color.White.copy(alpha = 0.3f),
                shape = RoundedCornerShape(12.dp)
            ).padding(8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Image(
            painter = painterResource(platformInfo.icon),
            contentDescription = null,
            modifier = Modifier.size(30.dp).clip(RoundedCornerShape(12.dp))
        )
        Text(
            text = platformInfo.title,
            color = Color.Black,
            style = GoldinThem.typoGraphy.titleMedium,
            fontWeight = FontWeight.Bold
        )
    }
}

@Composable
private fun PriceComponent(
    platformPrice: PlatformPrice,
    modifier: Modifier = Modifier,
) {
    val infiniteTransition = rememberInfiniteTransition()
    val scale by infiniteTransition.animateFloat(
        initialValue = 1f,
        targetValue = 1.05f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        )
    )

    Text(
        text = buildAnnotatedString {
            append(platformPrice.goldPrice.toString().byLocateAndSeparator())
            withStyle(style = GoldinThem.typoGraphy.titleMedium.toSpanStyle()) {
                append(" تومان")
            }
        },
        style = GoldinThem.typoGraphy.headlineMedium,
        color = Color.Black,
        fontWeight = FontWeight.ExtraBold,
        modifier = modifier.graphicsLayer {
            scaleX = scale
            scaleY = scale
        }
    )
}

@Composable
fun MobileGoldItem(
    modifier: Modifier = Modifier,
    platformPrice: NetworkResult<PlatformPrice>,
    info: PlatformInfo,
    onRefresh: () -> Unit = {}
) {
    val enableRefresh = when (platformPrice) {
        is NetworkResult.Error -> true
        NetworkResult.Idle -> false
        NetworkResult.Loading -> false
        is NetworkResult.Success -> true
    }
    Row(
        modifier = modifier
            .padding(8.dp)
            .pointerHoverIcon(PointerIcon.Hand)
            .clip(RoundedCornerShape(12.dp))
            .background(GoldinThem.colors.itemColor)
            .normalBoarder()
            .clickable(onClick = onRefresh, enabled = enableRefresh)
            .padding(12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(13.dp)
        )
        {
            Image(
                painter = painterResource(info.icon),
                contentDescription = null,
                modifier = Modifier.size(50.dp).clip(RoundedCornerShape(12.dp))
            )
            Column(
                verticalArrangement = Arrangement.spacedBy(5.dp)
            ) {
                Text(
                    text = info.title,
                    style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 19.sp),
                    color = GoldinThem.colors.textColor
                )
                Text(
                    text = if (platformPrice is NetworkResult.Success) platformPrice.data.lastTimeRefresh.toTehranJalaliDate() else "---",
                    style = GoldinThem.typoGraphy.bodyMedium,
                    color = GoldinThem.colors.textColor
                )
            }
        }
        when (platformPrice) {
            is NetworkResult.Error -> {
                Text(
                    text = "تلاش مجدد",
                    style = GoldinThem.typoGraphy.titleMedium,
                    color = Color.Red
                )
            }

            NetworkResult.Idle -> {
                Text(
                    text = "در انتظار اجرا",
                    style = GoldinThem.typoGraphy.titleMedium,
                    color = Color.Red
                )
            }

            NetworkResult.Loading -> {
                CircularProgressIndicator(
                    modifier = Modifier.size(20.dp),
                    color = GoldinThem.colors.textColor
                )
            }

            is NetworkResult.Success -> {
                Text(
                    text = buildAnnotatedString {
                        append(platformPrice.data.goldPrice.toString().byLocateAndSeparator())
                        withStyle(style = GoldinThem.typoGraphy.titleMedium.toSpanStyle()) {
                            append(" تومان")
                        }
                    },
                    style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 20.sp),
                    color = GoldinThem.colors.textColor
                )
            }
        }
    }
}
