val LocalTypography = compositionLocalOf<Typography> {
    error("not provide LocalTypography")
}
val LocalColors = compositionLocalOf<GoldinColors> {
    error("not provide LocalTypography")
}

object GoldinThem {

    val colors: GoldinColors
        @Composable
        @ReadOnlyComposable
        get() = LocalColors.current

    val typoGraphy: Typography
        @Composable
        @ReadOnlyComposable
        get() = LocalTypography.current
}

@Composable
fun GoldinTheme(
    darkTheme: Boolean?,
    content: @Composable () -> Unit,
) {
    val isDark = darkTheme ?: isSystemInDarkTheme()

    ThemeChangeAnimation(
        isDarkTheme = isDark
    ) { appliedIsDarkTheme ->
        val typography = GoldinTypoGraphy
        val windowSize = calculateWindowSizeInfo()
        val currentColors = if (appliedIsDarkTheme) GoldinDarkColor else GoldinLightColor
        CompositionLocalProvider(
            LocalLayoutDirection provides LayoutDirection.Rtl,
            LocalColors provides currentColors,
            LocalTypography provides typography,
            LocalWindowSize provides windowSize
        ) {
            content()
        }
    }
}

