package ir.hosein.goldin.ui.screen.setting

import goldin.shared.generated.resources.Res
import goldin.shared.generated.resources.ic_pc
import goldin.shared.generated.resources.ic_pc_outline
import goldin.shared.generated.resources.moon
import goldin.shared.generated.resources.moon_outline
import goldin.shared.generated.resources.sun
import goldin.shared.generated.resources.sun_outline
import org.jetbrains.compose.resources.DrawableResource

enum class ThemModel(
 val   title: String,
 val  selectedIcon: DrawableResource,
 val  unSelectedIcon: DrawableResource,
 val  darkAction: Boolean?
) {
    LIGHT(
        title = "روشن",
        selectedIcon = Res.drawable.sun,
        unSelectedIcon = Res.drawable.sun_outline,
        darkAction = false
    ),
    DARK(
        title = "تیره",
        selectedIcon = Res.drawable.moon,
        unSelectedIcon = Res.drawable.moon_outline,
        darkAction = true
    ),
    SYSTEM(
        title = "سیستم",
        selectedIcon = Res.drawable.ic_pc,
        unSelectedIcon = Res.drawable.ic_pc_outline,
        darkAction = null
    )

}