import ir.hosein.goldin.navigation.Routes
import org.jetbrains.compose.resources.DrawableResource

data class NavigationItem(
    val title: String,
    val route: Routes,
    val selectedIcon: DrawableResource,
    val unSelectedIcon: DrawableResource,
) {
    companion object {
        val mainNavigation = listOf(
            NavigationItem(
                title = "طلای دیجیتال",
                route = Routes.HomeScreen,
                selectedIcon = Res.drawable.ic_gold_selected,
                unSelectedIcon = Res.drawable.ic_gold,
            ),
            NavigationItem(
                title = "ارز خارجی",
                route = Routes.ArzScreen,
                selectedIcon = Res.drawable.ic_dolar_Selected,
                unSelectedIcon = Res.drawable.ic_dolar,
            ),
            NavigationItem(
                title = "رمز ارز",
                route = Routes.CryptoScreen,
                selectedIcon = Res.drawable.ic_crypto_selected,
                unSelectedIcon = Res.drawable.ic_crypto,
            ),
            NavigationItem(
                title = "تنظیمات ",
                route = Routes.SettingScreen(),
                selectedIcon = Res.drawable. ic_setting,
                unSelectedIcon = Res.drawable.ic_setting_selected,
            ),

            )
    }
}
