package ir.hosein.goldin.viewModel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import ir.hosein.goldin.data.core.NetworkResult
import ir.hosein.goldin.data.model.HomeUiState
import ir.hosein.goldin.data.model.PlatformInfo
import ir.hosein.goldin.data.model.PlatformPrice
import ir.hosein.goldin.repository.MainRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

class MainViewModel(
    private val mainRepository: MainRepository
) : ViewModel() {

    private val _homeUiState = MutableStateFlow(HomeUiState())
    val homeUiState = _homeUiState
        .asStateFlow()

    init {
        refreshAllPlatform()
    }

    fun onIntent(intent: HomeIntent) {
        when (intent) {
            HomeIntent.RefreshAllPlatform -> refreshAllPlatform()
            is HomeIntent.RefreshPlatform -> refreshPlatform(intent.platformInfo)
        }
    }

    private fun refreshAllPlatform() {
        PlatformInfo.entries.forEach { fetchPlatformData(it) }
    }

    private fun refreshPlatform(platformInfo: PlatformInfo) {
        fetchPlatformData(platformInfo)
    }

    private fun fetchPlatformData(info: PlatformInfo) {
        viewModelScope.launch {
            updateState(info, result = NetworkResult.Loading)
            val response = mainRepository.getPlatformPrice(info)
            updateState(info, result = response)
        }
    }

    private fun updateState(
        info: PlatformInfo,
        result: NetworkResult<PlatformPrice>
    ) {
        _homeUiState.update { state ->
            when (info) {
                PlatformInfo.DIGI_KALA -> state.copy(digiKalaState = result)
                PlatformInfo.MILI_GOLD -> state.copy(miliGoldState = result)
                PlatformInfo.TALASEA -> state.copy(talaseaGoldState = result)
                PlatformInfo.TALAPP -> state.copy(talappGoldState = result)
                PlatformInfo.GOLDIKA -> state.copy(goldikaGoldState = result)
                PlatformInfo.TALAIN -> state.copy(talainGoldState = result)
                PlatformInfo.WALL_GOLD ->  state.copy(wallGoldState = result)
                PlatformInfo.DARK ->  state.copy(daricGoldState = result)
            }
        }
    }
}