package ir.hosein.goldin.ui

import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.tooling.preview.Preview
import ir.hosein.goldin.navigation.GoldinNavDisplay
import ir.hosein.goldin.navigation.NavScaffold
import ir.hosein.goldin.ui.theme.GoldinTheme
import ir.hosein.goldin.viewModel.SettingViewModel
import org.koin.compose.viewmodel.koinViewModel

@Composable
@Preview
fun App() {
    val settingViewModel = koinViewModel<SettingViewModel>()
    val darkTheme by settingViewModel.darkThem.collectAsState(null)
    GoldinTheme(darkTheme = darkTheme) {
        NavScaffold{backStack->
            GoldinNavDisplay(
                backStack = backStack,
                darkThem = darkTheme,
                onChangeThem = {settingViewModel.saveThemDark(it)}
            )
        }
    }
}