package ir.hosein.goldin.util

import io.ktor.util.date.*

object Helper {
    fun String.byLocate(): String {
        return this.map {
            when (it) {
                '0' -> '۰'
                '1' -> '۱'
                '2' -> '۲'
                '3' -> '۳'
                '4' -> '۴'
                '5' -> '۵'
                '6' -> '۶'
                '7' -> '۷'
                '8' -> '۸'
                '9' -> '۹'
                else -> it
            }
        }.joinToString("")
    }

    fun String.bySeparator(): String {
        val clean = this.replace(",", "")
        if (clean.toLongOrNull() == null) return this
        return clean.replace(Regex("""(\d)(?=(\d{3})+(?!\d))"""), "$1,")
    }

    fun String.byLocateAndSeparator(): String {
        val separated = this.bySeparator()
        return separated.byLocate()
    }

    fun Long?.toTehranJalaliDate(): String {
        if (this == null) return "---"
        // Tehran is UTC + 3:30 (12600000 ms)
        val tehranTime = this + 12600000L
        val date = GMTDate(tehranTime)

        val jalali = gregorianToJalali(date.year, date.month.ordinal + 1, date.dayOfMonth)
        val year = jalali[0]
        val month = jalali[1].toString().padStart(2, '0')
        val day = jalali[2].toString().padStart(2, '0')
        val hour = date.hours.toString().padStart(2, '0')
        val minute = date.minutes.toString().padStart(2, '0')

        return "$hour:$minute -- $year/$month/$day".byLocate()
    }

    private fun gregorianToJalali(gy: Int, gm: Int, gd: Int): IntArray {
        val gDaysInMonth = intArrayOf(0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
        val gy2 = gy - 1600
        val gm2 = gm - 1
        val gd2 = gd - 1
        var gDayNo = 365 * gy2 + (gy2 + 3) / 4 - (gy2 + 99) / 100 + (gy2 + 399) / 400
        for (i in 0 until gm2) gDayNo += gDaysInMonth[i + 1]
        if (gm2 > 1 && ((gy2 % 4 == 0 && gy2 % 100 != 0) || (gy2 % 400 == 0))) gDayNo++
        gDayNo += gd2
        var jDayNo = gDayNo - 79
        val jNp = jDayNo / 12053
        jDayNo %= 12053
        var jy = 979 + 33 * jNp + 4 * (jDayNo / 1461)
        jDayNo %= 1461
        if (jDayNo >= 366) {
            jy += (jDayNo - 1) / 365
            jDayNo = (jDayNo - 1) % 365
        }
        var jm = 0
        var jd = 0
        for (i in 0..10) {
            val days = if (i < 6) 31 else 30
            if (jDayNo < days) {
                jm = i + 1
                jd = jDayNo + 1
                break
            }
            jDayNo -= days
        }
        if (jm == 0) {
            jm = 12
            jd = jDayNo + 1
        }
        return intArrayOf(jy, jm, jd)
    }
}
