import org.jetbrains.compose.resources.painterResource

@Composable
 fun RefreshHeader(
    title: String,
    onRefreshAll: () -> Unit
) {
    Row(
        modifier = Modifier.padding(12.dp)
            .fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = title,
            style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 19.sp),
            fontWeight = FontWeight.SemiBold,
            color = GoldinThem.colors.textColor
        )
        Box(
            modifier = Modifier
                .pointerHoverIcon(PointerIcon.Hand)
                .clip( RoundedCornerShape(14.dp))
                .border(
                    width = .8.dp,
                    color = GoldinThem.colors.goldColor,
                    shape = RoundedCornerShape(14.dp)
                )
                .clickable(onClick = onRefreshAll),
            contentAlignment = Alignment.Center
        ){
            Row(
                modifier = Modifier.padding(
                    horizontal = 10.dp,
                    vertical = 8.dp
                ),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = "به\u200Cروزرسانی سراسری",
                    style = GoldinThem.typoGraphy.bodyMedium,
                    color = GoldinThem.colors.textColor
                )
                Icon(
                    painter = painterResource(Res.drawable.ic_refresh),
                    contentDescription = null,
                    modifier = Modifier.size(18.dp),
                    tint = GoldinThem.colors.textColor
                )
            }

        }
    }
}