package ir.hosein.goldin.data.core

sealed interface NetworkResult<out T> {
    data object Idle : NetworkResult<Nothing>
    data object Loading : NetworkResult<Nothing>
    data class Success<T>(val data: T,val time: Long?=null) : NetworkResult<T>
    data class Error(val message: String) : NetworkResult<Nothing>

    fun <R> mapWithTime(transform: (T, Long?) -> R): NetworkResult<R> {
        return when (this) {
            is Success -> Success(transform(data, time), time)
            is Error -> Error(message)
            is Loading -> Loading
            is Idle -> Idle
        }
    }
}