package ir.hosein.goldin.ui.screen.setting

import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.widthIn
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.Scaffold
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalLayoutDirection
import androidx.compose.ui.unit.LayoutDirection
import androidx.compose.ui.unit.dp
import ir.hosein.goldin.ui.components.MainTopBar
import ir.hosein.goldin.ui.theme.GoldinThem

@Composable
fun SettingScreen(
    darkThem: Boolean?,
    onChangeThem: (value: Boolean?) -> Unit
) {
    Scaffold(
        topBar = { MainTopBar("تنظیمات") },
        containerColor = GoldinThem.colors.mainBackground,
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize(),
            contentAlignment = Alignment.TopCenter
        ) {
            Column(
                modifier = Modifier
                    .widthIn(max = 800.dp)
                    .fillMaxSize()
                    .verticalScroll(rememberScrollState())
                    .padding(innerPadding),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                SectionChangeThem(darkThem,onChangeThem)
                SectionSocialMedia()
            }
        }

    }
}


