package ir.hosein.goldin.viewModel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import ir.hosein.goldin.repository.SettingRepository
import kotlinx.coroutines.launch

class SettingViewModel(
    private val settingRepository: SettingRepository,
): ViewModel() {

    val darkThem = settingRepository.getThemeDark()

    fun saveThemDark(value: Boolean?){
        viewModelScope.launch { settingRepository.setThemeDark(value) }
    }
}