package ir.hosein.goldin.ui.components

import androidx.compose.animation.AnimatedContent
import androidx.compose.animation.SizeTransform
import androidx.compose.animation.core.tween
import androidx.compose.animation.fadeIn
import androidx.compose.animation.fadeOut
import androidx.compose.animation.slideInVertically
import androidx.compose.animation.slideOutVertically
import androidx.compose.animation.togetherWith
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Button
import androidx.compose.material3.ButtonDefaults
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import ir.hosein.goldin.data.core.NetworkResult
import ir.hosein.goldin.ui.theme.GoldinThem

@Composable
fun <T> HandleUiState(
    state: NetworkResult<T>,
    onRefreshAction: () -> Unit,
    content: @Composable (NetworkResult.Success<T>) -> Unit,
) {
    AnimatedContent(
        targetState = state,
        transitionSpec = {
            slideInVertically(
                initialOffsetY = { it / 2 },
                animationSpec = tween(300)
            ) + fadeIn(tween(300)) togetherWith
                    slideOutVertically(
                        targetOffsetY = { -it / 2 },
                        animationSpec = tween(300)
                    ) + fadeOut(tween(300)) using
                    SizeTransform(clip = false)
        }
    ) { result ->
        Box(
            modifier = Modifier.fillMaxSize(),
            contentAlignment = Alignment.Center
        ) {
            when (result) {
                is NetworkResult.Error -> {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Text(
                            text = "خطا: ${result.message}",
                            style = GoldinThem.typoGraphy.bodyLarge,
                            color = Color.Red
                        )
                        Button(
                            onClick = onRefreshAction,
                            colors = ButtonDefaults.buttonColors(
                                containerColor = GoldinThem.colors.goldColor,
                                contentColor = GoldinThem.colors.textColor
                            ),
                            modifier = Modifier.padding(top = 16.dp)
                        ) {
                            Text(
                                text = "تلاش مجدد",
                                style = GoldinThem.typoGraphy.bodyLarge,
                            )
                        }
                    }
                }
                NetworkResult.Idle -> { Text("آماده بارگذاری") }
                NetworkResult.Loading -> {
                    CircularProgressIndicator(color = GoldinThem.colors.textColor)
                }
                is NetworkResult.Success -> {
                    content(result)
                }
            }
        }
    }
}