package ir.hosein.goldin.viewModel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import ir.hosein.goldin.data.core.NetworkResult
import ir.hosein.goldin.data.model.ArzItem
import ir.hosein.goldin.repository.ArzRepository
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.onStart
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlin.time.Duration.Companion.milliseconds

class ArzViewModel(
    private val repository: ArzRepository
) : ViewModel() {

    private val _arzState = MutableStateFlow<NetworkResult<List<ArzItem>>>(NetworkResult.Idle)
    val arzState = _arzState.onStart { getArzList() }
        .stateIn(
            scope = viewModelScope,
            initialValue = NetworkResult.Idle,
            started = SharingStarted.Lazily
        )

    fun onIntent(intent: ArzIntent){
        when(intent){
            ArzIntent.RefreshAllPlatform -> getArzList()
        }
    }
    private fun getArzList() {
        viewModelScope.launch {
            _arzState.emit(NetworkResult.Loading)
            delay(1000.milliseconds)
            val response = repository.getArzList()
            _arzState.emit(response)
        }

    }
}