@OptIn(ExperimentalLayoutApi::class)
@Composable
fun SectionChangeThem(
    darkThem: Boolean?,
    onChangeThem: (value: Boolean?) -> Unit
) {
    val themeModels = remember { ThemModel.entries }

    Column(
        modifier = Modifier
            .padding(12.dp)
            .fillMaxWidth()
            .background(
                color = GoldinThem.colors.itemColor,
                shape = RoundedCornerShape(14.dp)
            )
            .padding(16.dp)
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Icon(
                painter = painterResource(Res.drawable.ic_theme),
                contentDescription = null,
                modifier = Modifier.size(24.dp),
                tint = GoldinThem.colors.textColor
            )
            Text(
                text = "تنظیمات ظاهر",
                style = GoldinThem.typoGraphy.titleLarge,
                color = GoldinThem.colors.textColor,
            )
        }

        Spacer(Modifier.height(20.dp))

        FlowRow(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Center,
        ) {
            themeModels.forEach { res ->
                SettingItem(
                    title = res.title,
                    selectedIcon = res.selectedIcon,
                    unSelectedIcon = res.unSelectedIcon,
                    selected = darkThem == res.darkAction,
                    onSelected = { onChangeThem(res.darkAction) }
                )

            }
        }
    }
}
