package ir.hosein.goldin.data.model

import ir.hosein.goldin.data.core.NetworkResult

data class HomeUiState(
    val digiKalaState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val miliGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val talappGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val talaseaGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val goldikaGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val daricGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val wallGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
    val talainGoldState: NetworkResult<PlatformPrice> = NetworkResult.Idle,
) {
    val platformsMap: Map<PlatformInfo, NetworkResult<PlatformPrice>> =
        mapOf(
            PlatformInfo.DIGI_KALA to digiKalaState,
            PlatformInfo.MILI_GOLD to miliGoldState,
            PlatformInfo.TALAPP to talappGoldState,
            PlatformInfo.TALASEA to talaseaGoldState,
            PlatformInfo.GOLDIKA to goldikaGoldState,
            PlatformInfo.DARK to daricGoldState,
            PlatformInfo.WALL_GOLD to wallGoldState,
            PlatformInfo.TALAIN to talainGoldState,
        )
    val allPlatforms: List<NetworkResult<PlatformPrice>> =
        platformsMap.values.toList()

    val bestPrice: PlatformPrice?
        get() = allPlatforms
            .filterIsInstance<NetworkResult.Success<PlatformPrice>>()
            .map { it.data }
            .minByOrNull { it.goldPrice }
}
