@Composable
fun CryptoScreen(cryptoViewModel: CryptoViewModel = koinViewModel()) {

    val cryptoState by cryptoViewModel.allCryptoList.collectAsState()
    val windowSize = LocalWindowSize.current
    val gridCells = remember(key1 = windowSize) {
        when (windowSize) {
            WindowSize.Compact -> 1
            WindowSize.Medium -> 2
            WindowSize.Expanded -> 3
        }
    }

    Scaffold(
        containerColor = GoldinThem.colors.mainBackground,
        topBar = { MainTopBar("رصد رمز ارز") }
    ) { innerPadding ->
        HandleUiState(
            state = cryptoState,
            onRefreshAction = { cryptoViewModel.onIntent(CryptoIntent.RefreshAllPlatform) },
        ) { response ->
            CompositionLocalProvider(
                LocalLayoutDirection provides LayoutDirection.Ltr
            ) {
                LazyVerticalGrid(
                    columns = GridCells.Fixed(gridCells),
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = innerPadding
                )
                {
                    item(span = { GridItemSpan(maxLineSpan) }, key = "header") {
                        CompositionLocalProvider(
                            LocalLayoutDirection provides LayoutDirection.Rtl
                        ) {
                            RefreshHeader(
                                title = "نبض بازار رمزارز ها",
                                onRefreshAll = { cryptoViewModel.onIntent(CryptoIntent.RefreshAllPlatform) }
                            )
                        }
                    }
                    items(response.data, key = { it.name }) { res ->
                        CryptoItemCard(
                            modifier = Modifier.animateItem(),
                            title = res.name,
                            price = res.current_price.toString(),
                            image = res.image
                        )
                    }
                }
            }

        }
    }
}


@Composable
private fun CryptoItemCard(
    modifier: Modifier,
    title: String,
    image: String,
    price: String,
) {
    Row(
        modifier = modifier
            .padding(8.dp)
            .clip(RoundedCornerShape(12.dp))
            .background(GoldinThem.colors.itemColor)
            .normalBoarder()
            .padding(12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            ImageLoader(
                model = image,
                modifier = Modifier
                    .size(35.dp)
                    .clip(CircleShape)
            )

            Text(
                text = title,
                style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 19.sp),
                color = GoldinThem.colors.textColor,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.fillMaxWidth(0.5f)
            )
        }

        Text(
            text = buildAnnotatedString {
                append(price.bySeparator())
                withStyle(style = GoldinThem.typoGraphy.titleMedium.toSpanStyle()) {
                    append(" $")
                }
            },
            style = GoldinThem.typoGraphy.titleMedium.copy(fontSize = 20.sp),
            color = GoldinThem.colors.textColor
        )

    }
}

